 static String responseHeaders(HttpResponse r){return r.headers()==null?"":String.join("\n",r.headers().stream().map(h->h.name()+": "+h.value()).toList());}
 static String decodedBody(String packet){int p=packet.indexOf("\r\n\r\n");if(p>=0)return packet.substring(p+4);p=packet.indexOf("\n\n");return p>=0?packet.substring(p+2):packet;}
 String baselineRoot(String url){java.net.URI uri=java.net.URI.create(url);String origin=EnvironmentCatalog.origin(uri),app=EnvironmentCatalog.prefix(prefix.getText());if(!app.isEmpty()&&!uri.getPath().equals(app)&&!uri.getPath().startsWith(app+"/"))app="";var site=catalog.sites.get(origin);if(app.isEmpty()&&site!=null)for(String root:site.prefixes)if((uri.getPath().equals(root)||uri.getPath().startsWith(root+"/"))&&root.length()>app.length())app=root;return origin+app;}
 void importWords(){if(job!=null)return;var site=catalog.sites.get(origins.getSelectedItem());if(site==null){status.setText("관찰된 대상을 먼저 선택하세요.");return;}JFileChooser chooser=new JFileChooser();if(chooser.showOpenDialog(this)!=JFileChooser.APPROVE_OPTION)return;try{var file=chooser.getSelectedFile().toPath();if(java.nio.file.Files.size(file)>1024*1024)throw new IllegalArgumentException("목록 파일은 1MiB 이하로 줄여주세요.");var result=EnvironmentDiscovery.importWords(site,java.nio.file.Files.readString(file),file.getFileName().toString());category="사용자 목록";refresh();status.setText("가져옴 "+result.accepted()+"개 · 중복/형식/제한 제외 "+result.skipped()+"개");}catch(Exception e){status.setText("목록 가져오기 실패 · "+e.getMessage());}}
 void stop(){stopping.set(true);status.setText("중지 중 · 이미 전송한 요청은 응답/10초 타임아웃 후 종료합니다.");}
 public void close(){targetSettings.close();candidateSettings.close();closed.set(true);stopping.set(true);packets.clear();catalog.sites.clear();origins.removeAllItems();refresh();}
